48	/** A selection range with orientation preserved: `anchor` is the drag/
49	 * extend origin, `head` is the current end — `head` may be before or after
50	 * `anchor` in document order ("backward" vs "forward"). */
51	export interface LineRange {
52	  readonly anchor: LinePos;
53	  readonly head: LinePos;
54	}
