56	function isEmpty(range: LineRange): boolean {
57	  return range.anchor.line === range.head.line && range.anchor.ch === range.head.ch;
58	}
59	
60	function posBefore(a: LinePos, b: LinePos): boolean {
61	  return a.line < b.line || (a.line === b.line && a.ch < b.ch);
62	}
63	
64	function isBackward(range: LineRange): boolean {
65	  return posBefore(range.head, range.anchor);
66	}
67	
68	function posEqual(a: LinePos, b: LinePos): boolean {
69	  return a.line === b.line && a.ch === b.ch;
70	}
