167	 * note; unchanged here, just extracted so both callers agree by
168	 * construction rather than by duplicated logic.
169	 */
170	function siblingRunCover(
171	  doc: OutlineDoc,
172	  anchorNode: OutlineNode,
173	  headNode: OutlineNode,
174	): { readonly nodes: readonly OutlineNode[]; readonly cover: Cover } {
175	  const anchorPath = findPath(doc, anchorNode.id)!;
176	  const headPath = findPath(doc, headNode.id)!;
177	
178	  let k = 0;
179	  while (k < anchorPath.length && k < headPath.length && anchorPath[k] === headPath[k]) k++;
180	  const scopeLen = k < anchorPath.length && k < headPath.length ? k : k - 1;
181	
182	  const scopePath = anchorPath.slice(0, scopeLen);
183	  const scopeChildren = childrenAtScope(doc, scopePath);
184	  const anchorIndex = anchorPath[scopeLen]!;
185	  const headIndex = headPath[scopeLen]!;
186	  const loIndex = Math.min(anchorIndex, headIndex);
187	  const hiIndex = Math.max(anchorIndex, headIndex);
188	  const nodes = scopeChildren.slice(loIndex, hiIndex + 1);
189	  const firstSubtree = nodes[0]!;
190	  const lastSubtree = nodes[nodes.length - 1]!;
191	
192	  return {
193	    nodes,
194	    cover: {
195	      start: { line: startLineOf(doc, firstSubtree), ch: 0 },
